export const drugs: Drug[] = rawDrugs.map((drug, index) => {
  const details = detailedDrugData[drug.name] ?? {};

  return {
    id: index + 1,
    ...drug,
    group: details.group ?? drug.category,
    mechanism: details.mechanism ?? "",
    effects: details.effects ?? "",
    indications: details.indications ?? "",
    contraindications: details.contraindications ?? "",
    sideEffects: details.sideEffects ?? "",
    dentalUse: details.dentalUse ?? "",
    krokNotes: details.krokNotes ?? "",
  };
});

export const getDrugById = (id: number) =>
  drugs.find((drug) => drug.id === id);

export const getDrugByName = (name: string) =>
  drugs.find((drug) => drug.name.toLowerCase() === name.toLowerCase());
